  ('f206b11f-f077-4a22-ae31-7f75735b4681', 'd4e5f6a7-8b9c-4e98-9b78-8f9a0b1c2d88', null, 'topic'::public.curated_course_node_type, 'Liberal Arts and Humanities: Purpose, Methods, and Public Value', 'This opening topic explains why humanities learning belongs in professional and design education: it builds judgment, interpretation, ethical awareness, cultural literacy, and the ability to connect specialized work to human contexts.', 0),
  ('437fddc3-c73e-4ba0-b1ba-b7f3408afeb5', 'd4e5f6a7-8b9c-4e98-9b78-8f9a0b1c2d88', 'f206b11f-f077-4a22-ae31-7f75735b4681', 'subtopic'::public.curated_course_node_type, 'What the humanities study', 'Students learn the range of humanistic inquiry: texts, images, artifacts, places, performances, beliefs, languages, institutions, and lived experience.', 0),
  ('54f131d2-83a9-4a04-af4b-97147062f0f4', 'd4e5f6a7-8b9c-4e98-9b78-8f9a0b1c2d88', '437fddc3-c73e-4ba0-b1ba-b7f3408afeb5', 'concept'::public.curated_course_node_type, 'Human meaning, memory, value, and expression', null, 0),
