  ('0edaf6ab-9be8-42a4-9464-6cb09de94076', 'd4e5f6a7-8b9c-4e98-9b78-8f9a0b1c2d88', '967a0b6b-cf20-4c76-bd88-9c80723f62de', 'concept'::public.curated_course_node_type, 'Competing interpretations', null, 2),
