  ('5fe51cc3-30cb-48c8-964d-210dd8293287', 'd4e5f6a7-8b9c-4e98-9b78-8f9a0b1c2d88', 'de518dbb-5fd8-4f3c-9a83-7bcab97b9f6a', 'subtopic'::public.curated_course_node_type, 'Logic and argument analysis', 'Students learn to identify valid reasoning, hidden assumptions, and weak inferences.', 0),
