  ('ec0c8bdc-4798-4712-a3d8-38a8800765b2', 'd4e5f6a7-8b9c-4e98-9b78-8f9a0b1c2d88', 'de518dbb-5fd8-4f3c-9a83-7bcab97b9f6a', 'subtopic'::public.curated_course_node_type, 'Ethical theories and moral judgment', 'Students compare major approaches to moral reasoning and apply them to difficult cases.', 1),
