  ('529e3892-565c-42ae-8ce5-a2d6bc580b60', 'd4e5f6a7-8b9c-4e98-9b78-8f9a0b1c2d88', 'ec0c8bdc-4798-4712-a3d8-38a8800765b2', 'concept'::public.curated_course_node_type, 'Rights, duties, harms, and goods', null, 1),
