  ('a20b5351-e333-4443-85db-af26cd9dd8a7', 'd4e5f6a7-8b9c-4e98-9b78-8f9a0b1c2d88', '7b825a0a-8077-4c0a-836e-397ba6fedee5', 'concept'::public.curated_course_node_type, 'Epistemology and skepticism', null, 0),
